INSERT INTO wine_vintages (id, wine_id, vintage_text, status, location_id, mevushal, supervision_display, special_designation, tasting_note, food_pairing, is_new, legacy) VALUES
  ('376831dd-feac-5002-ae98-45a7bd69c704', '727b84e4-31d7-5084-80fc-30c711737ec4', NULL, 'needs_review', 'b69f315a-60e0-5d80-94ae-c1bcf6f2ffe0', 'no', 'OU; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi', 'Grand Cru', 'This Corton displays an intense ruby color and has a broad bouquet of fruit accents (blueberry, redcurrant and cherry) moving towards pepper, leather and liquorice with age. On the palate, it is powerful and structured, with great sustain and body. It is firm, frank and fleshy.', 'Washed-rind and blue cheeses, roast or grilled beef joints and all roast or braised game or, of course, with a sauce.', false, '{"source": "mm_website", "website_slug": "aegerter-corton-vergennes", "name": "Aegerter Corton Vergennes", "producer": "Aegerter", "country": "France", "region": "Burgundy", "appellation": "Corton Grand Cru", "grapes": "100% Pinot Noir", "color": "Red", "mevushal": "No", "supervision": "OU; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi", "pairing": "Washed-rind and blue cheeses, roast or grilled beef joints and all roast or braised game or, of course, with a sauce.", "score": "", "img": "/images/images/aegerter-corton-vergennes.jpg?v=3", "new": false, "vintages": null, "tasting_note": "This Corton displays an intense ruby color and has a broad bouquet of fruit accents (blueberry, redcurrant and cherry) moving towards pepper, leather and liquorice with age. On the palate, it is powerful and structured, with great sustain and body. It is firm, frank and fleshy.", "expert_note": "“While there are still plenty of firm tannins, the wine also is now showing its red berry fruits and enticing texture. Great acidity cuts through the structure, giving freshness to the naturally dense character of this Grand Cru wine. It''s for aging, but not for too long” - Roger Voss", "serve": "slightly cool, 14 to 16°C (57 to 61°F).", "region_text": "Burgundy (\"Bourgogne\" in French) is an historic and highly respected wine region in eastern France. Burgundy wines have long had devout followers throughout the world and continue to do so today. Although Bordeaux produces about four times as much wine every year, Burgundy’s estimated 30,000 hectares (74,000 acres) of vineyards are considered to be of equal importance, producing some of the most exclusive wines on Earth. Burgundy wines come from several distinct sub-regions, each with its own particular character. Four of these are located at the heart of Burgundy, in a narrow strip running for 120km (75 miles) between the towns of Dijon and Mâcon. From north to south they are the Côte d''Or (comprising the Côte de Nuits and Côte de Beaune), the Côte Chalonnaise and the Mâconnais.", "grape_text": "Pinot Noir is the dominant red wine grape of Burgundy, now adopted (and extensively studied) in wine regions all over the world. The variety''s elusive charm has carried it to all manner of vineyards. These extend from western Germany (as Spätburgunder) and northern Italy to Chile, South Africa, Australia, New Zealand and the USA. California, Oregon and New Zealand are arguably the greatest centers for the grape outside its home territory. However great Pinot Noir is made in all of these territories.", "critical_acclaim": []}'::jsonb),
  ('7cd9bdbe-f8ad-5576-a3a1-155a9706ba6f', '31e8ec9e-d119-5878-bd91-659e1bad6c35', NULL, 'needs_review', 'de1a8275-a48e-5b84-9041-e1b2e9c10de2', 'no', 'OU; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi', NULL, 'Its purple robe, intense & sometimes moving towards mauve has a beautiful brilliance & offers a dense, sophisticated nose marked by aromas of blackcurrant & blueberry, enhanced by woody notes when young. Strong & vigorous, this full-bodied wine is chewwy, balanced & structured. Long in the mouth, it is fully appreciated after a few years’ keeping: maturity gives it a sensual, sophisticated roundness.', 'Washed-rind and Epoisses, Langres, or Soumaintrain. meats such as roast lamb, rib of beef, breast of duck or game.', false, '{"source": "mm_website", "website_slug": "aegerter-nuits-saint-georges", "name": "Aegerter Nuits-Saint-Georges", "producer": "Aegerter", "country": "France", "region": "Burgundy", "appellation": "Nuits-Saint-Georges", "grapes": "100% Pinot Noir", "color": "Red", "mevushal": "No", "supervision": "OU; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi", "pairing": "Washed-rind and Epoisses, Langres, or Soumaintrain. meats such as roast lamb, rib of beef, breast of duck or game.", "score": "", "img": "/images/images/aegerter-nuits-saint-georges.jpg?v=3", "new": false, "vintages": null, "tasting_note": "Its purple robe, intense & sometimes moving towards mauve has a beautiful brilliance & offers a dense, sophisticated nose marked by aromas of blackcurrant & blueberry, enhanced by woody notes when young. Strong & vigorous, this full-bodied wine is chewwy, balanced & structured. Long in the mouth, it is fully appreciated after a few years’ keeping: maturity gives it a sensual, sophisticated roundness.", "expert_note": "“The appellation alone arouses the desire to taste it... Nuits-Saint-Georges... This dense and racy wine offers a superb tasting with beautiful material, a silky texture and fine tannins announcing a pleasant wine for aging. A wine of pure pleasure synonymous with elegance and refinement. FANTASTIC ! ” - Jancis Robinson", "serve": "slightly cool, 14 to 16°C (57 to 61°F).", "region_text": "Burgundy (\"Bourgogne\" in French) is an historic and highly respected wine region in eastern France. Burgundy wines have long had devout followers throughout the world and continue to do so today. Although Bordeaux produces about four times as much wine every year, Burgundy’s estimated 30,000 hectares (74,000 acres) of vineyards are considered to be of equal importance, producing some of the most exclusive wines on Earth. Burgundy wines come from several distinct sub-regions, each with its own particular character. Four of these are located at the heart of Burgundy, in a narrow strip running for 120km (75 miles) between the towns of Dijon and Mâcon. From north to south they are the Côte d''Or (comprising the Côte de Nuits and Côte de Beaune), the Côte Chalonnaise and the Mâconnais.", "grape_text": "Pinot Noir is the dominant red wine grape of Burgundy, now adopted (and extensively studied) in wine regions all over the world. The variety''s elusive charm has carried it to all manner of vineyards. These extend from western Germany (as Spätburgunder) and northern Italy to Chile, South Africa, Australia, New Zealand and the USA. California, Oregon and New Zealand are arguably the greatest centers for the grape outside its home territory. However great Pinot Noir is made in all of these territories.", "critical_acclaim": []}'::jsonb),
  ('82940698-a5cb-55b9-b6af-3b072f3d2409', 'daef2876-5181-5bc3-8d68-b4c60f4eaead', NULL, 'needs_review', '26a7c27f-f567-5ff8-80ef-d477d528ce55', 'yes', 'Badatz – Beit Yosef ; OU', NULL, 'Intense salmon-pink in color, with generous aromas of sour cherry, strawberry jam & wild herbs. This wine is medium-boiled & fresh, with layers of bright fruit flavor, brisk acidity, & defining minerality that culminate in a long & balanced finish.', 'Perfect when paired with charcuterie board, meatball in tomato sauce grilled meat and chops.', false, '{"source": "mm_website", "website_slug": "botteotto-cabernet-sauvignon", "name": "Botteotto Cabernet Sauvignon", "producer": "Botteotto", "country": "Italy", "region": "Abruzzo", "appellation": "", "grapes": "100% Cabernet Sauvignon", "color": "Red", "mevushal": "Yes", "supervision": "Badatz – Beit Yosef ; OU", "pairing": "Perfect when paired with charcuterie board, meatball in tomato sauce grilled meat and chops.", "score": "", "img": "/images/images/botteotto-cabernet-sauvignon.jpg?v=3", "new": false, "vintages": null, "tasting_note": "Intense salmon-pink in color, with generous aromas of sour cherry, strawberry jam & wild herbs. This wine is medium-boiled & fresh, with layers of bright fruit flavor, brisk acidity, & defining minerality that culminate in a long & balanced finish.", "expert_note": "M & M teamed up with-the infamous Valle Reale Winery under the directorship of Leonardo Pizzolo. Excellent quality Price Ratio in kosher market and certified organic. Botteotto means barrel number eight and was the barrel that originally contained the wine that inspired the final blend. The grapes for Botteotto are harvested by hand and the various vineyards are vinified separately. -Certified Organic Biodynamic Wine", "serve": "at 17 to 18°C (63 to 65°F).", "region_text": "Although the rediscovery of ancient varieties is always welcome, the focus in Abruzzo remains firmly on Montepulciano. It’s a versatile grape, in the sense that it can give pleasure in numerous guises. It can be vinified and aged in stainless steel to give a simple, attractive wine with freshness and transparency of fruit. If cropped low, it can be aged in casks or barriques – even new barriques – to create wines of altogether greater depth, concentration and complexity. The oaked Montepulcianos are not really wines for everyday drinking, being too dense and powerful, but are superb winter warmers. Some can develop gamey aromas with age; others remain on a plateau, displaying primary fruit for years. Montepulciano does evolve with age, but it’s not a variety that demands bottle age to show complexity.", "grape_text": "Cabernet Sauvignon is probably the most famous red wine grape variety on Earth. It is rivaled in this regard only by its Bordeaux stablemate Merlot, and its opposite number in Burgundy, Pinot Noir. From its origins in Bordeaux, Cabernet has successfully spread to almost every winegrowing country in the world. It is now the key grape variety in many first-rate New World wine regions, most notably Napa Valley, Coonawarra and Maipo Valley. Wherever they come from, Cabernet Sauvignon wines always seem to demonstrate a handful of common character traits: deep color, good tannin structure, moderate acidity and aromas of blackcurrant, tomato leaf, dark spices and cedarwood.", "critical_acclaim": []}'::jsonb),
  ('77c3df10-72d4-5e3c-93c7-ed8d9f376af7', '2ae2e6a1-fdae-5da8-a1b5-d44d49dd50af', NULL, 'needs_review', '26a7c27f-f567-5ff8-80ef-d477d528ce55', 'yes', 'Badatz – Beit Yosef ; OU', 'IGT', 'Intense salmon-pink in color, with generous aromas of sour cherry, strawberry jam & wild herbs. This wine is medium-boiled & fresh, with layers of bright fruit flavor, brisk acidity, & defining minerality that culminate in a long & balanced finish.', 'Enjoy with warm fish appetizers, fresh cheese sushi, shashimi & fish tartar', false, '{"source": "mm_website", "website_slug": "botteotto-cerasuolo-dabruzzo-rose", "name": "Botteotto Cerasuolo D’Abruzzo Rosé", "producer": "Botteotto", "country": "Italy", "region": "Abruzzo", "appellation": "IGT", "grapes": "100% Montepulciano", "color": "Rosé", "mevushal": "Yes", "supervision": "Badatz – Beit Yosef ; OU", "pairing": "Enjoy with warm fish appetizers, fresh cheese sushi, shashimi & fish tartar", "score": "", "img": "/images/images/botteotto-cerasuolo-d-abruzzo-ros-.jpg?v=3", "new": false, "vintages": null, "tasting_note": "Intense salmon-pink in color, with generous aromas of sour cherry, strawberry jam & wild herbs. This wine is medium-boiled & fresh, with layers of bright fruit flavor, brisk acidity, & defining minerality that culminate in a long & balanced finish.", "expert_note": "M & M teamed up with the infamous Valle Reale Winery under the directorship of Leonardo Pizzolo. Excellent quality Price Ratio in kosher market and certified organic. Botteotto means barrel number eight and was the barrel that originally contained the wine that inspired the final blend. The grapes for Botteotto are harvested by hand and the various vineyards are vinified separately. -Certified Organic Biodynamic Wine", "serve": "chilled, 8 to 10°C (46 to 50°F).", "region_text": "Although the rediscovery of ancient varieties is always welcome, the focus in Abruzzo remains firmly on Montepulciano. It’s a versatile grape, in the sense that it can give pleasure in numerous guises. It can be vinified and aged in stainless steel to give a simple, attractive wine with freshness and transparency of fruit. If cropped low, it can be aged in casks or barriques – even new barriques – to create wines of altogether greater depth, concentration and complexity. The oaked Montepulcianos are not really wines for everyday drinking, being too dense and powerful, but are superb winter warmers. Some can develop gamey aromas with age; others remain on a plateau, displaying primary fruit for years. Montepulciano does evolve with age, but it’s not a variety that demands bottle age to show complexity.", "grape_text": "Montepulciano is a red wine grape grown widely in central Italy, most notably its eastern Abruzzo, Marche and Molise regions. However, it is not planted in Montepulciano in southern Tuscany (see below). The variety is used mainly to produce dry red wines. A notable exception can be found in the lighter, cherry colored Cerasuolo d''Abruzzo. Montepulciano wines are globally appreciated for their soft flavors and strong color pigments. Gentle tannins and a low acidity create a medium bodied wine that is typically best consumed soon after bottling. Although, the variety also responds well to a judicious use of oak to create a richer, age-worthy style of wine. The deep purple juice is used in varying proportions under roughly 50 of Italy''s DOC and DOCG titles. The most famous wines from the variety come from the east coast of Italy, specifically the Abruzzo region. It is produced under the Montepulciano d’Abruzzo DOC title in vast volumes on the low hills around the Adriatic coast.", "critical_acclaim": []}'::jsonb),
  ('bc1c6519-2d9e-53e6-8ce8-5fe1ac2586b7', '2c14fa1d-6e0e-5009-af45-8114595735d3', NULL, 'needs_review', 'f968a820-2161-50b4-9c5f-2cab5b9e0064', 'no', 'Badatz – Beit Yosef ; OU', 'IGT', 'It presents a golden yellow color. Complex and intense nose characterized by apricot aroma,yellow peaches, white flowers, spices and honey. In the mouth a sweet exotic intensity combined with a pleasant freshness which makes it very harmonious.', 'Excellent with raw fish & fried fish pasta dishes based on fish. You can also try it with medium-aged cheeses.', false, '{"source": "mm_website", "website_slug": "botteotto-grigio-xm6p7-w95x6", "name": "Tirsat Gurra di Mare", "producer": "", "country": "Italy", "region": "Sicily", "appellation": "IGT Terre Siciliane", "grapes": "50% Viognier; 50% Chardonnay", "color": "White", "mevushal": "No", "supervision": "Badatz – Beit Yosef ; OU", "pairing": "Excellent with raw fish & fried fish pasta dishes based on fish. You can also try it with medium-aged cheeses.", "score": "", "img": "/images/images/tirsat.png?v=3", "new": false, "vintages": null, "tasting_note": "It presents a golden yellow color. Complex and intense nose characterized by apricot aroma,yellow peaches, white flowers, spices and honey. In the mouth a sweet exotic intensity combined with a pleasant freshness which makes it very harmonious.", "expert_note": "M & M teamed up witThe vineyards stretch as far as the beach, occupying a terrain that varies from clay to sandy and with small streams that release nutrients and mineral salts to the vineyards before flowing into the sea. -", "serve": "chilled, 8 to 10°C (46 to 50°F).", "region_text": "A warm, dry Mediterranean climate prevails on the coast of this large island, but it is more temperate and moist in the inland mountains. Southerly winds bring dry air to the region. The red variety of greatest importance is Nero d’Avola, and white varieties to look for are Grillo, Catarratto and Inzolia.", "grape_text": "Chardonnay – Viognier is a blend of two white-wine grape varieties produced in a number of countries around the world. Chardonnay is often cited as being the world''s most famous white-wine variety, and is best known for its revered varietal expressions in Burgundy. Less known but still important, Viognier creates weighty, fruit-driven wines, most famously in France''s Rhone Valley but also notably in Australia. Together, these two varieties form full-bodied white wines. The general structure and versatility of Chardonnay is complemented here by Viognier’s floral aromas, and the union of the two grapes can produce a weighty wine that shows lavender and apricot accents. The natural acid of Chardonnay is an asset to the blend as, without it, the wine may be flabby, or lack focus.", "critical_acclaim": []}'::jsonb),
  ('2e248824-a534-5a5d-b0b2-ac4923e850c1', 'af285121-b797-5177-b402-72872c61c715', NULL, 'needs_review', '26a7c27f-f567-5ff8-80ef-d477d528ce55', 'yes', 'Badatz – Beit Yosef ; OU', 'IGT', 'Brilliant yellow color. The flower contribution of orange blossom, daisy & white wisteria develops in ripe fruit notes: apricot, peach, white melon. Sweet sensations of custard and crème brûlé. The palate is Full & progressive. Pineapple, melon, pear, peach & sweet pastry notes enhanced by lively freshness & pleasant.', 'Antipasti, fried fish, vegetables, light pasta sauces and sushi', false, '{"source": "mm_website", "website_slug": "botteotto-grigio-xm6p7", "name": "Botteotto Pinot Grigio", "producer": "Botteotto", "country": "Italy", "region": "Abruzzo", "appellation": "IGT", "grapes": "100% Pinot Grigio", "color": "White", "mevushal": "Yes", "supervision": "Badatz – Beit Yosef ; OU", "pairing": "Antipasti, fried fish, vegetables, light pasta sauces and sushi", "score": "", "img": "/images/images/pinot-grigio.png?v=3", "new": false, "vintages": null, "tasting_note": "Brilliant yellow color. The flower contribution of orange blossom, daisy & white wisteria develops in ripe fruit notes: apricot, peach, white melon. Sweet sensations of custard and crème brûlé. The palate is Full & progressive. Pineapple, melon, pear, peach & sweet pastry notes enhanced by lively freshness & pleasant.", "expert_note": "M & M teamed up with-the infamous Valle Reale Winery under the directorship of Leonardo Pizzolo. Excellent quality Price Ratio in kosher market and certified organic. Botteotto means barrel number eight and was the barrel that originally contained the wine that inspired the final blend. The grapes for Botteotto are harvested by hand and the various vineyards are vinified separately. -Certified Organic Biodynamic Wine", "serve": "chilled, 8 to 10°C (46 to 50°F).", "region_text": "Although the rediscovery of ancient varieties is always welcome, the focus in Abruzzo remains firmly on Montepulciano. It’s a versatile grape, in the sense that it can give pleasure in numerous guises. It can be vinified and aged in stainless steel to give a simple, attractive wine with freshness and transparency of fruit. If cropped low, it can be aged in casks or barriques – even new barriques – to create wines of altogether greater depth, concentration and complexity. The oaked Montepulcianos are not really wines for everyday drinking, being too dense and powerful, but are superb winter warmers. Some can develop gamey aromas with age; others remain on a plateau, displaying primary fruit for years. Montepulciano does evolve with age, but it’s not a variety that demands bottle age to show complexity.", "grape_text": "Pinot Grigio is the Italian name for Pinot Gris, a white mutation of the Pinot family. It shares its genetic fingerprint with Pinot Noir, Pinot Blanc and several other varieties. The term Pinot Grigio has become strongly associated with light bodied wines produced in great quantities, particularly in northern Italy. The wines are most commonly described as dry white wines with relatively high acidity. These characteristics are complemented by aromas of lemon, lime, green apple and blossoms. This \"everyday\" Grigio Italian style is achieved firstly by harvesting the grapes relatively early. This is done in an attempt to retain as much fresh acidity as possible. Otherwise the variety is naturally quite low in acidity. In a hot summer, the picking date is particularly important.", "critical_acclaim": []}'::jsonb),
  ('8db5ab46-ba10-5652-b1ae-d3d31b2e42fa', 'e5488b36-17b1-5fad-9533-330a35a13c98', NULL, 'needs_review', '26a7c27f-f567-5ff8-80ef-d477d528ce55', 'yes', 'Badatz – Beit Yosef ; OU', 'IGT', 'Valle Reale "Botteotto" has a spicy, fruity flavor with hints of barrels, dark cherries, sage, currants, chocolate and vanilla.', 'Pizzas, fatty beef burgers. Other meats that fare well with this wine include roast beef, beef brisket, and shepherds pie.', false, '{"source": "mm_website", "website_slug": "botteotto-montepulciano-dabruzzo", "name": "Botteotto Montepulciano D’Abruzzo", "producer": "Botteotto", "country": "Italy", "region": "Abruzzo", "appellation": "IGT", "grapes": "100% Montepulciano", "color": "Red", "mevushal": "Yes", "supervision": "Badatz – Beit Yosef ; OU", "pairing": "Pizzas, fatty beef burgers. Other meats that fare well with this wine include roast beef, beef brisket, and shepherds pie.", "score": "", "img": "/images/images/botteotto-montepulciano-d-abruzzo.jpg?v=3", "new": false, "vintages": null, "tasting_note": "Valle Reale \"Botteotto\" has a spicy, fruity flavor with hints of barrels, dark cherries, sage, currants, chocolate and vanilla.", "expert_note": "M & M teamed up with the infamous Valle Reale Winery under the directorship of Leonardo Pizzolo. Excellent quality Price Ratio in kosher market and certified organic. Botteotto means barrel number eight and was the barrel that originally contained the wine that inspired the final blend. The grapes for Botteotto are harvested by hand and the various vineyards are vinified separately. -Certified Organic Biodynamic Wine", "serve": "at 16 to 17°C (61 to 63°F).", "region_text": "Although the rediscovery of ancient varieties is always welcome, the focus in Abruzzo remains firmly on Montepulciano. It’s a versatile grape, in the sense that it can give pleasure in numerous guises. It can be vinified and aged in stainless steel to give a simple, attractive wine with freshness and transparency of fruit. If cropped low, it can be aged in casks or barriques – even new barriques – to create wines of altogether greater depth, concentration and complexity. The oaked Montepulcianos are not really wines for everyday drinking, being too dense and powerful, but are superb winter warmers. Some can develop gamey aromas with age; others remain on a plateau, displaying primary fruit for years. Montepulciano does evolve with age, but it’s not a variety that demands bottle age to show complexity.", "grape_text": "Montepulciano is a red wine grape grown widely in central Italy, most notably its eastern Abruzzo, Marche and Molise regions. However, it is not planted in Montepulciano in southern Tuscany (see below). The variety is used mainly to produce dry red wines. A notable exception can be found in the lighter, cherry colored Cerasuolo d''Abruzzo. Montepulciano wines are globally appreciated for their soft flavors and strong color pigments. Gentle tannins and a low acidity create a medium bodied wine that is typically best consumed soon after bottling. Although, the variety also responds well to a judicious use of oak to create a richer, age-worthy style of wine. The deep purple juice is used in varying proportions under roughly 50 of Italy''s DOC and DOCG titles. The most famous wines from the variety come from the east coast of Italy, specifically the Abruzzo region. It is produced under the Montepulciano d’Abruzzo DOC title in vast volumes on the low hills around the Adriatic coast.", "critical_acclaim": []}'::jsonb),
  ('6759c0b0-655e-505d-a139-9669078b875d', '87c1f6ed-45af-5dfc-94a5-98607342aa7b', NULL, 'needs_review', '26a7c27f-f567-5ff8-80ef-d477d528ce55', 'yes', 'Badatz – Beit Yosef ; OU', 'IGT', 'Pale straw with a gentle sparkle. Peach, apricot, orange blossom and honeysuckle. Lightly sweet, fresh and low in alcohol.', 'Fruit desserts, cheesecake, spicy Asian dishes, brunch.', false, '{"source": "mm_website", "website_slug": "botteotto-moscato", "name": "Botteotto Moscato", "producer": "Botteotto", "country": "Italy", "region": "Abruzzo", "appellation": "IGT", "grapes": "100% Moscato", "color": "White", "mevushal": "Yes", "supervision": "Badatz – Beit Yosef ; OU", "pairing": "Fruit desserts, cheesecake, spicy Asian dishes, brunch.", "score": "", "img": "/images/images/botteotto-moscato.jpg?v=3", "new": false, "vintages": null, "tasting_note": "Pale straw with a gentle sparkle. Peach, apricot, orange blossom and honeysuckle. Lightly sweet, fresh and low in alcohol.", "expert_note": "M & M teamed up with the infamous Valle Reale Winery under the directorship of Leonardo Pizzolo. Excellent quality Price Ratio in kosher market and certified organic. Botteotto means barrel number eight and was the barrel that originally contained the wine that inspired the final blend. The grapes for Botteotto are harvested by hand and the various vineyards are vinified separately. -Certified Organic Biodynamic Wine", "serve": "chilled, 8 to 10°C (46 to 50°F).", "region_text": null, "grape_text": null, "critical_acclaim": []}'::jsonb),
  ('4a3e91a5-18be-5fe1-ac3b-e2903b3a5853', '6e83fcbe-316a-5e9c-a04f-8e68c4ee88ab', '2022', 'needs_review', '2a81a8d5-8b39-5c95-be88-1b0115fa6cc8', 'no', 'OU ; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi', 'DOCG', 'Bright ruby red color with purple highlights. Thanks to the harmony of the tannins, combined with the delicate complexity of aromas and the final note of sweetness, the wine is characterized by an excellent balance in the mouth.', 'A very versatile wine, ideally paired with structured main dishes. It also goes well with stewed dishes and medium-aged cheeses.', false, '{"source": "mm_website", "website_slug": "castellare-chianti-classico", "name": "Castellare Chianti Classico", "producer": "Castellare di Castellina", "country": "Italy", "region": "Tuscany", "appellation": "DOCG", "grapes": "100% Sangiovese", "color": "Red", "mevushal": "No", "supervision": "OU ; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi", "pairing": "A very versatile wine, ideally paired with structured main dishes. It also goes well with stewed dishes and medium-aged cheeses.", "score": "92 Vinous", "img": "/images/images/castellare-chianti-classico.jpg?v=4", "new": false, "vintages": "2022", "tasting_note": "Bright ruby red color with purple highlights. Thanks to the harmony of the tannins, combined with the delicate complexity of aromas and the final note of sweetness, the wine is characterized by an excellent balance in the mouth.", "expert_note": null, "serve": "at 16 to 17°C (61 to 63°F).", "region_text": "The scenic hills of Tuscany are home to the cities of Florence and Siena, as well as to Chianti, a blend made primarily from the Sangiovese grape. It was once known as an inexpensive table wine marked by its bulbous bottle and woven base, but efforts by innovative winemakers have produced very fine examples that have made the wine world reconsider the cliché. Chianti is a dry, medium-bodied wine with high acids, moderate tannins and flavors of cherry, herbs and sweet spice. One of the most aged and revered wines in Italy is Brunello di Montalcino, made entirely from a clone of Sangiovese grown near the town of Montalcino. It is a medium- to full-bodied dry wine that tastes of black fruits, earth and pepper.", "grape_text": "Sangiovese (or Nielluccio in Corsica), a dark-berried vine, is the most widely planted grape variety in Italy. Virtually synonymous with the red wines of Tuscany, and all the romanticism that goes with the territory, Sangiovese is the core constituent in some of the great names in Italian wine. Italy''s love affair with Sangiovese – and indeed the world''s – is generations old, though recent grapevine research suggests the variety is not as ancient as once thought.", "critical_acclaim": [{"score": "92", "critic": "Vinous", "context": "2022 vintage", "quote": "Silky, aromatic, and light on its feet."}, {"score": "91", "critic": "James Suckling", "context": "2022 vintage", "quote": null}, {"score": "90", "critic": "Wine Spectator", "context": "2022 vintage", "quote": "Big sour-cherry and spice nose with notes of tobacco leaf."}]}'::jsonb),
  ('87b8f4b2-cd26-52db-b347-4d56a10cb896', 'faec44e8-a1c3-5852-808b-4ebcd69dfa6f', NULL, 'needs_review', '31c483b5-ee62-505a-a6e2-f40c8f02e5ee', 'no', 'OU; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi', 'AOC', 'Deep dark red. Nose: Deep and intense; notes of ripe fruit, cedar and tobacco, with toasted and mineral nuances. Mouth: Powerful and complex, with notes of ripe fruit, black currant and wood; smooth tannins; fresh and spicy finish.', 'Ideal with classic meat dishes, veal, beef, lamb, duck, game, roast chicken, roasted, braised and grilled dishes.', false, '{"source": "mm_website", "website_slug": "chateau-la-tour-de-by", "name": "Chateau La Tour de By", "producer": "Château La Tour de By", "country": "France", "region": "Bordeaux", "appellation": "AOC", "grapes": "50% Cabernet Sauvignon, 50% Merlot", "color": "Red", "mevushal": "No", "supervision": "OU; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi", "pairing": "Ideal with classic meat dishes, veal, beef, lamb, duck, game, roast chicken, roasted, braised and grilled dishes.", "score": "", "img": "/images/images/chateau-la-tour-de-by.jpg?v=3", "new": false, "vintages": null, "tasting_note": "Deep dark red. Nose: Deep and intense; notes of ripe fruit, cedar and tobacco, with toasted and mineral nuances. Mouth: Powerful and complex, with notes of ripe fruit, black currant and wood; smooth tannins; fresh and spicy finish.", "expert_note": "Chateau La Tour de By is a special cuvee and is most often produced from a blend of 50% Cabernet Sauvignon and 50% Merlot. It is tannic but yet very approachable and classic in style with a peppery, cassis fruit center but it needs time for the cassis to soften and come around.", "serve": "at 17 to 18°C (63 to 65°F).", "region_text": "The Médoc district of Bordeaux is an area of coastal lagoons, sand dunes and pine forests located on the 45th parallel. It is also a global wine powerhouse, and home to four of the world''s most prestigious wine villages: Pauillac, Margaux, Saint-Estèphe and Saint-Julien. The estates located in these villages produce some of the world''s most expensive bottles. The region also provided all but one (Haut-Brion) of the châteaux included in the official 1855 Classification of Bordeaux wines.", "grape_text": "Cabernet Sauvignon – Merlot wines are made from two of the world''s most famous and most widely grown wine grapes. The pair form the foundation of many of the great wines of Bordeaux, where this classic blend (often dubbed \"Bordeaux Blend\") is thought to have originated. For centuries, Cabernet Sauvignon and Merlot have been the quintessential Bordeaux wine grapes, but their fame and popularity have now taken them far beyond the banks of the Garonne, Dordogne and Gironde, to the furthest reaches of the wine world. In California the blend is often labeled as Meritage – providing the producer meets the requirements of the Meritage Alliance. The Australian regions of Coonawarra, Margaret River and Yarra Valley are highly regarded for their unique expressions of the blend. South Africa''s Stellenbosch region also produces some earthy and savory examples that defy many of the commonly held perceptions about New World wine. In other New World countries the blend is often abbreviated to Cabernet Merlot, although this mix could include Cabernet Franc as well.", "critical_acclaim": []}'::jsonb),
  ('2d948ec6-4a44-51fb-a8a8-6e951df35905', '5db4568d-f4eb-52dc-bcdd-9f67626ee1aa', '2020', 'needs_review', '96a80d85-8e78-5a86-a451-e3d5916eedac', 'no', 'OU; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi', NULL, 'Color is dark and almost impenetrable purple with exuberant nose ripe blackberries, black plums, sweet tobacco as well as toasted oak and vanilla. This is a delicious, very well made, firmly structured, modem, sexy, Parker style Margaux.', 'Classic meat dishes, veal, beef, lamb, duck, game, roast chicken. Asian dishes, hearty fish courses like tuna, salmon, mushrooms and pasta as well as cheese.', false, '{"source": "mm_website", "website_slug": "chateau-labegorce-margaux", "name": "Chateau Labegorce Margaux", "producer": "Château Labégorce", "country": "France", "region": "Bordeaux", "appellation": "Margaux", "grapes": "50% Cabernet Sauvignon, 50% Merlot", "color": "Red", "mevushal": "No", "supervision": "OU; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi", "pairing": "Classic meat dishes, veal, beef, lamb, duck, game, roast chicken. Asian dishes, hearty fish courses like tuna, salmon, mushrooms and pasta as well as cheese.", "score": "93 Vinous", "img": "/images/images/chateau-labegorce-margaux.jpg?v=3", "new": false, "vintages": "2020, 2015", "tasting_note": "Color is dark and almost impenetrable purple with exuberant nose ripe blackberries, black plums, sweet tobacco as well as toasted oak and vanilla. This is a delicious, very well made, firmly structured, modem, sexy, Parker style Margaux.", "expert_note": null, "serve": "at 17 to 18°C (63 to 65°F). Decant young vintages for an hour.", "region_text": "Margaux is an important appellation in the Haut-Médoc district of Bordeaux, southwestern France. Located 25 kilometers (15 miles) north of the city of Bordeaux, the appellation is famous for producing supple, perfumed wines, predominantly from Cabernet Sauvignon. The Margaux appellation contains 21 cru classé properties from the 1855 Bordeaux Classification (20 of which still exist), more than any other Left Bank appellation. It is also, geographically speaking, the largest in the Médoc, and is divided into five communes or parishes. In the north, Soussans borders Pauillac. It boasts no cru classé wines, unlike the commune of Margaux to its south.", "grape_text": "Cabernet Sauvignon – Merlot wines are made from two of the world''s most famous and most widely grown wine grapes. The pair form the foundation of many of the great wines of Bordeaux, where this classic blend (often dubbed \"Bordeaux Blend\") is thought to have originated. For centuries, Cabernet Sauvignon and Merlot have been the quintessential Bordeaux wine grapes, but their fame and popularity have now taken them far beyond the banks of the Garonne, Dordogne and Gironde, to the furthest reaches of the wine world.", "critical_acclaim": [{"score": "93", "critic": "James Suckling", "context": "2020 vintage", "quote": "A tight, compact Labégorce. Very structured for this estate."}, {"score": "93", "critic": "Vinous", "context": "2020 vintage", "quote": "A dark, sumptuous beauty."}, {"score": "91", "critic": "Robert Parker''s Wine Advocate", "context": "2020 vintage", "quote": "Fleshy and layered, this contemporary-styled Margaux."}, {"score": "16.5/20", "critic": "Jancis Robinson", "context": "2020 vintage", "quote": null}]}'::jsonb),
  ('1beb52db-7f1c-526b-9de4-0c32247c8df8', '5db4568d-f4eb-52dc-bcdd-9f67626ee1aa', '2015', 'needs_review', '96a80d85-8e78-5a86-a451-e3d5916eedac', 'no', 'OU; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi', NULL, 'Color is dark and almost impenetrable purple with exuberant nose ripe blackberries, black plums, sweet tobacco as well as toasted oak and vanilla. This is a delicious, very well made, firmly structured, modem, sexy, Parker style Margaux.', 'Classic meat dishes, veal, beef, lamb, duck, game, roast chicken. Asian dishes, hearty fish courses like tuna, salmon, mushrooms and pasta as well as cheese.', false, '{"source": "mm_website", "website_slug": "chateau-labegorce-margaux", "name": "Chateau Labegorce Margaux", "producer": "Château Labégorce", "country": "France", "region": "Bordeaux", "appellation": "Margaux", "grapes": "50% Cabernet Sauvignon, 50% Merlot", "color": "Red", "mevushal": "No", "supervision": "OU; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi", "pairing": "Classic meat dishes, veal, beef, lamb, duck, game, roast chicken. Asian dishes, hearty fish courses like tuna, salmon, mushrooms and pasta as well as cheese.", "score": "93 Vinous", "img": "/images/images/chateau-labegorce-margaux.jpg?v=3", "new": false, "vintages": "2020, 2015", "tasting_note": "Color is dark and almost impenetrable purple with exuberant nose ripe blackberries, black plums, sweet tobacco as well as toasted oak and vanilla. This is a delicious, very well made, firmly structured, modem, sexy, Parker style Margaux.", "expert_note": null, "serve": "at 17 to 18°C (63 to 65°F). Decant young vintages for an hour.", "region_text": "Margaux is an important appellation in the Haut-Médoc district of Bordeaux, southwestern France. Located 25 kilometers (15 miles) north of the city of Bordeaux, the appellation is famous for producing supple, perfumed wines, predominantly from Cabernet Sauvignon. The Margaux appellation contains 21 cru classé properties from the 1855 Bordeaux Classification (20 of which still exist), more than any other Left Bank appellation. It is also, geographically speaking, the largest in the Médoc, and is divided into five communes or parishes. In the north, Soussans borders Pauillac. It boasts no cru classé wines, unlike the commune of Margaux to its south.", "grape_text": "Cabernet Sauvignon – Merlot wines are made from two of the world''s most famous and most widely grown wine grapes. The pair form the foundation of many of the great wines of Bordeaux, where this classic blend (often dubbed \"Bordeaux Blend\") is thought to have originated. For centuries, Cabernet Sauvignon and Merlot have been the quintessential Bordeaux wine grapes, but their fame and popularity have now taken them far beyond the banks of the Garonne, Dordogne and Gironde, to the furthest reaches of the wine world.", "critical_acclaim": [{"score": "93", "critic": "James Suckling", "context": "2020 vintage", "quote": "A tight, compact Labégorce. Very structured for this estate."}, {"score": "93", "critic": "Vinous", "context": "2020 vintage", "quote": "A dark, sumptuous beauty."}, {"score": "91", "critic": "Robert Parker''s Wine Advocate", "context": "2020 vintage", "quote": "Fleshy and layered, this contemporary-styled Margaux."}, {"score": "16.5/20", "critic": "Jancis Robinson", "context": "2020 vintage", "quote": null}]}'::jsonb),
  ('69abe965-e0e5-5338-8ff7-84784a75fe17', '5716e038-aab5-5a3c-985f-7338f651eeff', '2022', 'needs_review', 'eed6cf23-3d67-5777-82b6-35fe0e748762', 'no', 'OU; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi', '4ème Grand Cru Classé', 'The nose is pleasing, open, fruity, and oaky with notes of fresh pepper. The wine is agreeable and elegant in the mouth, with a subtle attack despite the boldness and power of the mid-palate and finish. The aromas are fruity, smoky and salty. This is a well-made and nicely structured wine.', 'Classic meat dishes, veal, beef, lamb, duck, game, roast chicken, Asian dishes, hearty fish courses like tuna, mushrooms and pasta.', false, '{"source": "mm_website", "website_slug": "chateau-lafon-rochet", "name": "Chateau Lafon-Rochet", "producer": "Château Lafon-Rochet", "country": "France", "region": "Bordeaux", "appellation": "Saint-Estèphe 4ème Grand Cru Classé", "grapes": "65% Cabernet Sauvignon, 31% Merlot, 4% Cabernet Franc (2022)", "color": "Red", "mevushal": "No", "supervision": "OU; Rabbi Its’hak Katz Kehal Yereim Paris Chareidi", "pairing": "Classic meat dishes, veal, beef, lamb, duck, game, roast chicken, Asian dishes, hearty fish courses like tuna, mushrooms and pasta.", "score": "96 Vinous", "img": "/images/images/chateau-lafon-rochet.jpg?v=3", "new": false, "vintages": "2022, 2020", "tasting_note": "The nose is pleasing, open, fruity, and oaky with notes of fresh pepper. The wine is agreeable and elegant in the mouth, with a subtle attack despite the boldness and power of the mid-palate and finish. The aromas are fruity, smoky and salty. This is a well-made and nicely structured wine.", "expert_note": null, "serve": "at 17 to 18°C (63 to 65°F). Decant young vintages for an hour.", "region_text": "Saint-Estèphe is one of the many famous Left Bank red wine appellations of Bordeaux, known for reds based on Cabernet Sauvignon and Merlot. Situated at the northern end of the Haut-Médoc region on the gravelly western shores of the Gironde estuary, Saint-Estèphe is separated from its famous neighbor, Pauillac, only by a stream, yet there are significant differences between them. With 1,229 hectares (3036 acres) it accounts for 8 percent of the vineyard area of the Médoc. Because Saint-Estèphe is marginally further from the gravel-bearing waters of the Garonne river, the soil here is far less stony than that found in the southern part of Haut-Médoc. Instead, a heavy clay and limestone base dominates this area, resulting in poorer-draining soils, delayed ripening and higher acidity levels in the wines.", "grape_text": "Cabernet Franc – Cabernet Sauvignon are two of the key grape varieties (along with Merlot) used in the red wines of Bordeaux. The combined blend of the two has been so successful that it has been adopted in wine regions the world over. Typically Cabernet Sauvignon is the dominant member in this blend, and provides both structure (acidic and tannic) and aromatic complexity (cassis, cedar, tobacco). The Cabernet Franc component brings a lifted, slightly more floral aroma, and a hint of spice on the palate. Exceptions to this rule of Cabernet Sauvignon dominance are most likely to be found in the Loire Valley, where Cabernet Franc has long been a staple red wine variety. In Tuscany this blend has been warmly adopted. Sassicaia – one of Italy''s most famous wines – is arguably one of the world''s finest examples of this marriage of the two Cabernet grapes, and is largely responsible for the proliferation of the style throughout the region. This \"Super Tuscan\" wine is routinely described as having characteristics of cassis and five-spice with firm tannins in its youth. With age these wines soften and start to show more secondary qualities – often led by Cabernet Franc – of tobacco, coffee and earthy minerals.", "critical_acclaim": [{"score": "96", "critic": "Vinous", "context": "2022 vintage", "quote": "Once again, the most elegant wine in Saint-Estèphe."}, {"score": "95", "critic": "Decanter", "context": "2022 vintage", "quote": "An exceptional wine in 2022."}, {"score": "95", "critic": "Jeb Dunnuck", "context": "2022 vintage", "quote": "A seriously good, concentrated, powerful expression."}, {"score": "94", "critic": "James Suckling", "context": "2022 vintage", "quote": "Dark chocolate, cigar box, blackcurrants, white pepper and graphite."}, {"score": "94", "critic": "Jane Anson", "context": "2022 vintage", "quote": null}, {"score": "91", "critic": "Robert Parker''s Wine Advocate", "context": "2022 vintage", "quote": "A rich, ripe, somewhat Napa-styled Saint-Estèphe."}, {"score": "96", "critic": "Vinous", "context": "2020 vintage", "quote": "Represents the essence of classicism in Bordeaux."}, {"score": "95", "critic": "Wine Enthusiast", "context": "2020 vintage", "quote": "Richly structured, powered by dark tannins and rich blackberry fruits."}, {"score": "94", "critic": "Decanter", "context": "2020 vintage", "quote": "Pleasingly silky, polished and smooth. Sheer pleasure!"}, {"score": "93", "critic": "Jeb Dunnuck", "context": "2020 vintage", "quote": null}, {"score": "90", "critic": "Wine Spectator", "context": "2020 vintage", "quote": "Plump and open, with a burst of loganberry and mulberry fruit."}]}'::jsonb),
