  ('4bb30df6-6a4b-5fd5-a645-0bc1b46df3a8', 'f33c408c-7600-5f08-97c1-95db1d794b52', '2022', 'needs_review', '3cbd7332-628d-5064-a0b7-2f1f650cfe27', 'unknown', NULL, 'Grand Cru', NULL, 'Roast rack of lamb, standing rib roast, duck breast with cherry sauce, mushroom and herb stuffed veal', true, '{"source": "mm_website", "website_slug": "carillon-d-angelus", "name": "Carillon d''Angélus", "producer": "Château Angélus", "country": "France", "region": "Bordeaux", "appellation": "Saint-Émilion Grand Cru", "grapes": "Merlot, Cabernet Franc", "color": "Red", "mevushal": "", "supervision": "", "pairing": "Roast rack of lamb, standing rib roast, duck breast with cherry sauce, mushroom and herb stuffed veal", "score": "95 JS", "img": "/images/images/carillon-d-angelus.webp?v=3", "new": true, "vintages": "2020, 2022", "tasting_note": null, "expert_note": null, "serve": "at 17 to 18°C (63 to 65°F). Decant young vintages for an hour.", "region_text": null, "grape_text": null, "critical_acclaim": [{"score": "95", "critic": "James Suckling", "context": "2020 vintage", "quote": "Linear and tight with fresh and fine tannins."}, {"score": "92 to 94", "critic": "Vinous", "context": "2020, barrel sample", "quote": "I cannot recall a Carillon as precise as this."}, {"score": "16.5/20", "critic": "Jancis Robinson", "context": "2020 vintage", "quote": null}]}'::jsonb),
